export async function fetchWeather(city) {
  const geoUrl = new URL("https://geocoding-api.open-meteo.com/v1/search");
  geoUrl.searchParams.set("name", city);
  geoUrl.searchParams.set("count", "1");
  const geo = await fetch(geoUrl).then((r) => r.json());
  if (!geo.results?.length) throw new Error("Город не найден");
  const { latitude, longitude, name } = geo.results[0];
  const wxUrl = new URL("https://api.open-meteo.com/v1/forecast");
  wxUrl.searchParams.set("latitude", latitude);
  wxUrl.searchParams.set("longitude", longitude);
  wxUrl.searchParams.set("current", "temperature_2m");
  const wx = await fetch(wxUrl).then((r) => r.json());
  return { name, temp: wx.current.temperature_2m };
}
